(async () => {
 const wait=()=>new Promise(r=>setTimeout(r,160)),check=(v,m)=>{if(!v)throw Error(m)},state=()=>JSON.parse(localStorage.getItem('collaboration-prototype-v1'));
 const go=async p=>{location.hash=p;await wait()},dialog=()=>document.querySelector('dialog[open]');
 const click=async(t,scope=document)=>{const b=[...scope.querySelectorAll('button')].find(b=>(b.textContent.trim()===t||b.getAttribute('aria-label')===t)&&!b.disabled&&b.getAttribute('role')!=='combobox');check(b,'Missing enabled '+t);b.click();await wait()};
 const fill=async(label,value)=>{const e=document.querySelector(`[aria-label="${label}"]`)||document.querySelector(`[name="${label}"]`);check(e,'Missing field '+label);Object.getOwnPropertyDescriptor(e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(e,value);e.dispatchEvent(new Event('input',{bubbles:true}));await wait()};
 const choose=async(label,text)=>{const c=document.querySelector(`[role=combobox][aria-label="${label}"]`);check(c,'Missing combo '+label);c.click();await wait();const o=[...document.querySelectorAll('[role=option]')].find(o=>o.textContent.trim()===text);check(o,'Missing option '+text);o.click();await wait()};
 const tab=async text=>{const e=[...dialog().querySelectorAll('[role=tab]')].find(e=>e.textContent.trim()===text);if(e){e.click();await wait()}else await click(text,dialog())};
 const checks=[],project=state().projects.find(p=>p.id==='launch');
 await go('/chat?channel_id=launch');await click('创建频道');await choose('所属项目',project.name);await fill('频道名称','review_channel');await fill('频道主题','首轮核验');await click('创建频道',dialog());
 const id=state().channels.find(c=>c.name==='review_channel')?.id;check(id,'Create missing');const current=()=>state().channels.find(c=>c.id===id);check(document.querySelector('.chat-heading h1').textContent.includes('review_channel'),'Create did not select channel');
 await click('频道设置');await fill('频道名称','review_final');await fill('频道主题','最终核验');await click('保存频道资料');check(current().name==='review_final','Edit missing');checks.push('source UI create and edit');
 await tab('成员');const before=JSON.stringify(current());const owner=[...dialog().querySelectorAll('li')].find(li=>li.textContent.includes('林予'));await click('设为成员',owner);check(JSON.stringify(current())===before,'Last owner changed');check(dialog().querySelector('[role=alert]'),'Missing last-owner error');
 const errorFocused=()=>{const a=dialog().querySelector('[role=alert]'),r=a?.getBoundingClientRect(),body=dialog().querySelector('.modal-body')?.getBoundingClientRect();check(a===document.activeElement&&r.top>=Math.max(0,body?.top||0)&&r.bottom<=Math.min(innerHeight,body?.bottom||innerHeight),'Business refusal not focused and visible');};errorFocused();await click('设为成员',owner);errorFocused();check(JSON.stringify(current())===before,'Repeated last-owner refusal changed state');
 await choose('添加成员','周宁');await click('添加成员',dialog());check(current().members.some(m=>m.principalId==='H-zhou'&&!m.leftAt),'Member missing '+JSON.stringify(current().members)+' '+dialog().innerText);let row=[...dialog().querySelectorAll('li')].find(li=>li.textContent.includes('周宁'));await click('设为所有者',row);check(current().members.find(m=>m.principalId==='H-zhou').role==='OWNER','Promotion missing');row=[...dialog().querySelectorAll('li')].find(li=>li.textContent.includes('周宁'));await click('移除',row);check(current().members.find(m=>m.principalId==='H-zhou').leftAt,'Member history missing');checks.push('last owner refusal atomic; add promote remove retain history');
 await tab('公告');await fill('公告正文','固定公告一');await click('发布公告');const first=current().announcement.messageId;await click('载入公告修订');await fill('公告正文','固定公告二');await click('发布修订公告');const second=current().announcement.messageId;check(first!==second&&current().announcement.revision===2,'Announcement revision missing');await click('取消公告');check(current().announcement.cancelledAt&&state().messages.find(m=>m.id===first).text==='固定公告一'&&state().messages.find(m=>m.id===second).text==='固定公告二','Announcement history erased');checks.push('publish revise cancel immutable announcements');
 await tab('钩子');check(dialog().textContent.includes('尚未连接投递服务'),'Hook implies connected');await fill('HTTPS 公网目标地址（支持普通查询参数）','https://example.com/hooks?group=review');const enabled=[...dialog().querySelectorAll('label')].find(l=>l.textContent.includes('保存为配置启用')).querySelector('input');enabled.click();await wait();await click('新增钩子配置');check(current().hooks.length===1&&current().hooks[0].configuredEnabled,'Hook config missing');await click('脱敏载荷预览');check(document.querySelector('.channel-payload').textContent.includes('NOT_CONNECTED'),'False runtime');await click('编辑配置');await fill('HTTPS 公网目标地址（支持普通查询参数）','https://example.com/hooks?group=changed');await click('保存钩子修改');check(current().hooks[0].revision===2,'Hook edit missing');await click('停用');check(!current().hooks[0].configuredEnabled,'Disable missing');await click('启用配置');await click('撤销');check(current().hooks[0].revokedAt,'Revoke missing');checks.push('hook configure edit preview disable revoke honest NOT_CONNECTED');
 await tab('详情');await fill('归档理由','本轮结束');await click('归档关闭频道');check(current().archivedAt,'Archive missing');check([...dialog().querySelectorAll('button')].find(b=>b.textContent.trim()==='保存频道资料').disabled,'Archive still writable');await tab('历史');check(dialog().textContent.includes('归档')&&dialog().textContent.includes('固定公告一'),'History missing');await tab('详情');await fill('恢复理由','继续核验');await click('恢复频道');check(!current().archivedAt&&!current().hooks[0].configuredEnabled&&current().hooks[0].revokedAt,'Restore re-enabled hook');checks.push('archive readonly retained history restore leaves hook disabled');
 await click('关闭弹窗',dialog());if(document.querySelector('dialog[open]'))await click('放弃修改',dialog());
 const url=location.href,len=history.length;const target=[...document.querySelectorAll('.channel-list a.panel-button')].find(b=>b.textContent.includes(project.name));check(target,'Channel nav missing');target.click();await wait();check(new URLSearchParams(location.hash.split('?')[1]).get('channel_id')===project.id&&history.length===len+1,'Channel switch must synchronize target URL and one history entry');check(document.querySelector('.chat-heading h1').textContent.includes(project.name),'Channel did not switch');checks.push('channel switch synchronizes target URL and one history entry');
 await go('/agents/atlas');check(document.querySelector('main').textContent.includes('任务编组不等于频道成员'),'Missing assignment disclaimer');const workBefore=JSON.stringify(state().work);await choose('授权项目',project.name);await fill('授权或撤销说明','仅此项目会话读取');await click('保存明确授权');let grant=state().channelProjectGrants.find(g=>g.agentId==='atlas'&&g.projectId==='launch');check(grant&&JSON.stringify(grant.permissions)==='["channel_read"]'&&JSON.stringify(state().work)===workBefore,'Grant changed task rights');await click('核对 / 修改 / 撤销');await fill('授权或撤销说明','撤销会话范围');await click('撤销此项目会话授权');grant=state().channelProjectGrants.find(g=>g.agentId==='atlas'&&g.projectId==='launch');check(grant.revokedAt&&grant.history.length>=2,'Grant revoke history missing');checks.push('Agent explicit project read grant and revoke without work assignment changes');
 await go('/settings');await choose('角色视角','external');for(const p of ['/chat?channel_id=private','/chat?channel_id=external&thread_id='+encodeURIComponent(state().messages.find(m=>m.channel==='private').id)]){await go(p);check(!document.querySelector('.composer'),'External private thread writable');check(!document.querySelector('.messages'),'External private thread exposed');}checks.push('external private channel and forged thread rejected');
 await go('/settings');await choose('角色视角','owner');await go('/chat?channel_id='+id);check(document.documentElement.scrollWidth<=innerWidth,'Viewport overflow');return {pass:true,width:innerWidth,id,checks};
})();
